// Robustly handle response structure (Array vs {items:[]})
const responseData = items[0].json;
const leads = Array.isArray(responseData) ? responseData : (responseData.items || []);

const now = new Date();
const updates = [];

for (const lead of leads) {
  if (!lead.lastInteraction) continue;

  const lastInteraction = new Date(lead.lastInteraction);
  const diffMs = now - lastInteraction;
  const diffHours = diffMs / (1000 * 60 * 60);

  let newStatus = null;

  // Skip terminal states
  if (['WON', 'LOST'].includes(lead.status)) continue;

  // Logic: > 48 hours -> COLD
  if (diffHours > 48) {
    if (lead.status !== 'COLD') newStatus = 'COLD';
  }
  // Logic: > 2 hours -> NEEDS_FOLLOWUP
  else if (diffHours > 2) {
    if (lead.status !== 'NEEDS_FOLLOWUP' && lead.status !== 'COLD') {
      newStatus = 'NEEDS_FOLLOWUP';
    }
  }

  // Only add to output if status actually changes
  if (newStatus) {
    updates.push({
      json: {
        id: lead.id,
        name: lead.name,
        oldStatus: lead.status,
        newStatus: newStatus,
        hoursSinceInteraction: Math.round(diffHours * 10) / 10
      }
    });
  }
}

return updates;
